int main(int argc,char**){CHECK(CoInitializeEx(nullptr,COINIT_MULTITHREADED));auto dll=LoadLibraryW(L"BandHeartBeatDirectShow-test.dll");if(!dll)return 2;auto get=reinterpret_cast<HRESULT(WINAPI*)(REFCLSID,REFIID,void**)>(GetProcAddress(dll,"DllGetClassObject"));const CLSID id={0x5b4131af,0x3298,0x47aa,{0x9c,0x12,0x33,0x40,0x7a,0x81,0x91,0x4b}};ComPtr<IClassFactory>factory;CHECK(get(id,IID_PPV_ARGS(&factory)));ComPtr<IBaseFilter>source;CHECK(factory->CreateInstance(nullptr,IID_PPV_ARGS(&source)));ComPtr<IGraphBuilder>graph;CHECK(CoCreateInstance(CLSID_FilterGraph,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&graph)));ComPtr<IBaseFilter>renderer;CHECK(CoCreateInstance(CLSID_NullRenderer,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&renderer)));CHECK(graph->AddFilter(source.Get(),L"BandHeartBeat isolated"));CHECK(graph->AddFilter(renderer.Get(),L"Quartz NullRenderer"));ComPtr<IPin>output,input;CHECK(source->FindPin(L"Output",&output));ComPtr<IEnumPins>pins;CHECK(renderer->EnumPins(&pins));CHECK(pins->Next(1,&input,nullptr));AM_MEDIA_TYPE* selected=nullptr;if(argc>1){ComPtr<IAMStreamConfig>config;CHECK(output.As(&config));int count=0,bytes=0;CHECK(config->GetNumberOfCapabilities(&count,&bytes));std::vector<BYTE>caps(bytes);CHECK(config->GetStreamCaps(1,&selected,caps.data()));if(selected->subtype!=MEDIASUBTYPE_RGB24)return 7;}CHECK(graph->ConnectDirect(output.Get(),input.Get(),selected));if(selected){CoTaskMemFree(selected->pbFormat);CoTaskMemFree(selected);}ComPtr<IAMDroppedFrames>stats;CHECK(output.As(&stats));ComPtr<IMediaControl>control;CHECK(graph.As(&control));CHECK(control->Run());Sleep(1200);long n=0;CHECK(stats->GetNumNotDropped(&n));CHECK(control->Stop());if(n<20||n>45){std::cerr<<"unexpected deliveries "<<n<<"\n";return 3;}std::cout<<"PASS real Quartz FilterGraph -> NullRenderer accepted "<<n<<" samples in1200ms (nominal30fps)\n";CHECK(control->Run());Sleep(300);CHECK(control->Stop());long again;CHECK(stats->GetNumNotDropped(&again));if(again<=n)return 4;CHECK(graph->Disconnect(output.Get()));CHECK(graph->Disconnect(input.Get()));CHECK(graph->RemoveFilter(renderer.Get()));CHECK(graph->RemoveFilter(source.Get()));stats.Reset();control.Reset();input.Reset();output.Reset();pins.Reset();renderer.Reset();graph.Reset();source.Reset();factory.Reset();auto unload=reinterpret_cast<HRESULT(WINAPI*)()>(GetProcAddress(dll,"DllCanUnloadNow"));CHECK(unload());FreeLibrary(dll);CoUninitialize();std::cout<<"PASS graph stop/restart/disconnect/unload; no registry/physical camera\n";}

